import { gs, GlideDateTime, GlideRecord } from '@servicenow/glide'

export function createOnboardingRecord(current, previous) {
    // Only create onboarding record when a new tenant is created
    if (current.isNewRecord()) {
        var onboardingGr = new GlideRecord('x_146833_tenant_on_onboarding');
        onboardingGr.initialize();
        onboardingGr.setValue('tenant', current.getUniqueValue());
        onboardingGr.setValue('onboarding_stage', 'registration');
        onboardingGr.setValue('started_date', new GlideDateTime().getDisplayValue());
        onboardingGr.setValue('progress_percentage', 10);
        onboardingGr.setValue('current_task', 'Review tenant registration and validate information');
        onboardingGr.setValue('priority', 'medium');

        // Set target completion date to 14 days from now
        var targetDate = new GlideDateTime();
        targetDate.addDaysUTC(14);
        onboardingGr.setValue('target_completion_date', targetDate.getDisplayValue());

        onboardingGr.insert();

        gs.addInfoMessage('Onboarding process initiated for tenant: ' + current.getDisplayValue());
    }
}

export function updateTenantStatus(current, previous) {
    // Update tenant status when onboarding stage changes
    var tenantGr = new GlideRecord('x_146833_tenant_on_tenant');
    if (tenantGr.get(current.getValue('tenant'))) {
        var stage = current.getValue('onboarding_stage');

        switch (stage) {
            case 'complete':
                tenantGr.setValue('tenant_status', 'active');
                tenantGr.setValue('is_active', true);
                tenantGr.setValue('approved_date', new GlideDateTime().getDisplayValue());
                current.setValue('actual_completion_date', new GlideDateTime().getDisplayValue());
                current.setValue('progress_percentage', 100);
                break;
            case 'failed':
                tenantGr.setValue('tenant_status', 'rejected');
                tenantGr.setValue('is_active', false);
                break;
            case 'approval':
                current.setValue('progress_percentage', 90);
                break;
            case 'testing':
                current.setValue('progress_percentage', 75);
                break;
            case 'technical_setup':
                current.setValue('progress_percentage', 50);
                break;
            case 'documentation':
                current.setValue('progress_percentage', 30);
                break;
            case 'review':
                current.setValue('progress_percentage', 20);
                break;
        }

        tenantGr.update();
    }
}

export function setRegistrationDate(current, previous) {
    // Set registration date when tenant is first created
    if (current.isNewRecord()) {
        current.setValue('registration_date', new GlideDateTime().getDisplayValue());
    }
}
